from autore import Modulo,estratto
from tikz_base import scrivi,n,a,rect,linea
m=Modulo('M06','Confrontare gruppi e valutare ipotesi','Contrasti, distribuzioni di riferimento e interpretazione dell’evidenza')
def p(t,s,**kw):m.pagina(t,s,**kw)
def d(i,b):return scrivi('M06',i,b)
m.sezione_nuova('Disegno, contrasto e ipotesi')
p('Il contrasto formalizza la domanda scientifica',
'''Il confronto fra gruppi richiede una quantità che rappresenti la differenza di interesse. Nel caso dei fossili sintetici, il contrasto è definito come diametro medio degli Spiky meno diametro medio dei Rounded, così che il segno mantenga un’interpretazione costante. L’ipotesi nulla stabilisce un valore di riferimento, mentre l’alternativa delimita gli scostamenti pertinenti alla domanda. La scelta della direzione deve precedere la lettura dell’esito, poiché modifica la procedura e la distribuzione delle decisioni.''',formula=r'\Delta=\mu_S-\mu_R,\qquad H_0:\Delta=0\\ H_1:\Delta\ne0\quad\text{oppure}\quad H_1:\Delta>0',destra='Nel modulo si utilizza principalmente l’alternativa bilaterale. Le unità del contrasto sono micrometri; le ipotesi riguardano medie di popolazioni descritte dal modello, mentre la differenza campionaria ne fornisce una stima.',richiamo='Definizione, verso e unità del contrasto devono precedere il calcolo del test.',origine='M06:1–10,13–15')
p('Il disegno stabilisce la struttura della dipendenza',
'''Due campioni indipendenti e due misure sugli stessi provini contengono relazioni differenti fra le osservazioni. Nel disegno appaiato, l’identificativo permette di calcolare una differenza entro ogni coppia, eliminando la componente comune del livello individuale. Nei dati raggruppati per sito può esistere invece dipendenza anche fra provini distinti. Il diagramma distingue queste strutture, mostrando perché la numerosità delle righe debba essere interpretata rispetto alle unità indipendenti effettivamente disponibili.''',tikz=d('D01',n(1.7,.4,'Indipendenti',w=3)+n(5.7,.4,'Appaiati',w=3)+''.join(n(1,1.6+j,chr(65+j))+n(2.5,1.6+j,str(j+1))+n(4.8,1.6+j,f'P{j+1}')+a(5.25,1.6+j,6.1,1.6+j)+n(6.6,1.6+j,f'P{j+1}') for j in range(3))+n(5.7,5.5,'Stesso identificativo nelle due condizioni.',w=3.3,size=11)),richiamo='La procedura deve rispettare abbinamenti, raggruppamenti e unità indipendenti del disegno.',origine='M06:11–12,52,57')
p('La distribuzione osservata precede il test',
'''Il grafico dei diametri conserva le osservazioni individuali e le medie dei due morfotipi. La differenza stimata è circa 0,582 µm, mentre le distribuzioni mostrano una sovrapposizione consistente. Il confronto inferenziale valuterà l’incertezza della differenza delle medie sotto le ipotesi dichiarate, anziché trasformare la separazione grafica in una regola di classificazione dei singoli fossili. La natura sintetica dei dati delimita inoltre l’interpretazione geologica dell’esempio.''',figura='M06/F01',didascalia='Ottanta fossili sintetici per morfotipo. I rombi indicano le medie; il lieve jitter orizzontale separa i punti.',richiamo='La differenza fra medie e la separazione fra individui descrivono proprietà diverse.',origine='M06:12,48,53–55')

m.sezione_nuova('Permutazione e scambiabilità')
p('La permutazione costruisce un riferimento nullo',
'''Se le osservazioni provengono dalla stessa distribuzione e sono indipendenti, le etichette dei gruppi sono scambiabili sotto l’ipotesi nulla. La permutazione mantiene i valori osservati e riassegna le etichette, ricostruendo le differenze compatibili con tale riferimento. In un esperimento randomizzato, la distribuzione delle assegnazioni può derivare direttamente dal disegno. La sola uguaglianza delle medie, in presenza di varianze o distribuzioni diverse, è invece insufficiente a giustificare la permutazione semplice della differenza non standardizzata.''',formula=r'T_{\rm obs}=\bar x_S-\bar x_R,\qquad T^\pi=\bar x_S^\pi-\bar x_R^\pi',tikz=d('D02',n(1.8,.4,'Valori osservati')+n(5.7,.4,'Etichette')+''.join(n(1.8,1.4+j*.8,str(v))+n(5.7,1.4+j*.8,g) for j,(v,g) in enumerate([(4,'S'),(6,'S'),(5,'R'),(8,'R')]))+a(4.7,1.4,4.7,3.8,'Quantum')+a(6.7,3.8,6.7,1.4)+n(3.7,5.5,'I valori rimangono fissati; cambia l’assegnazione.',w=6.8,size=11)),richiamo='La validità della permutazione deriva dalla scambiabilità o dalla randomizzazione prevista nel disegno.',origine='M06:16–20,24–25')
p('Il confronto con le permutazioni',
'''La distribuzione delle differenze permutate descrive lo scostamento che può emergere riassegnando gruppi della stessa numerosità. Per un confronto bilaterale basato sul valore assoluto, si contano le repliche almeno altrettanto estreme del risultato osservato. Se vengono campionate B permutazioni casuali, l’aggiunta dell’assegnazione osservata conduce alla forma con uno al numeratore e al denominatore, evitando di attribuire probabilità nulla soltanto perché il campionamento numerico ha trovato poche code.''',formula=r'\widehat p=\frac{1+\sum_{b=1}^B\mathbf1(|T_b^\pi|\ge|T_{\rm obs}|)}{B+1}',figura='M06/F02',didascalia='Quattromila permutazioni dei morfotipi; le linee verticali individuano ±|T osservato|.',richiamo='Il numero delle permutazioni limita la risoluzione del p-value Monte Carlo.',origine='M06:21–22,24–25')
c=estratto('M06','permutazione',"d <- read.csv('dati/fossili_simulati.csv')\nx <- d$diametro_tot_um\ng <- d$morfotipo=='Spiky'\nstat <- function(g) mean(x[g])-mean(x[!g])\nobs <- stat(g); set.seed(602)\nB <- 4000L\ntp <- replicate(B,stat(sample(g)))\n(1+sum(abs(tp)>=abs(obs)))/(B+1)")
p('Bootstrap e permutazione hanno riferimenti diversi',
'''Nel bootstrap si ricampiona per approssimare la variabilità di uno stimatore rispetto a una distribuzione stimata dai dati. Nella permutazione si ricostruisce invece una distribuzione di riferimento attraverso riassegnazioni ammesse sotto l’ipotesi nulla. Il codice conserva la numerosità dei gruppi e calcola sempre il contrasto nello stesso verso. Per dati appaiati, temporali o raggruppati, una riassegnazione libera delle righe può distruggere la struttura che il disegno richiede di conservare.''',codice=c,richiamo='La procedura di ricampionamento deve corrispondere alla distribuzione che si intende approssimare.',origine='M06:18–25')

m.sezione_nuova('P-value e contenuto dell’evidenza')
p('Il p-value è calcolato sotto un riferimento',
'''Il p-value misura la probabilità, nel modello nullo e secondo una regola di estremità prefissata, di ottenere una statistica almeno altrettanto estrema di quella osservata. La probabilità è quindi condizionata al riferimento utilizzato nel calcolo. Attribuire tale numero all’ipotesi nulla richiederebbe un diverso impianto inferenziale, con una distribuzione sulle ipotesi. La lettura frequentista deve mantenere esplicite le condizioni del modello, poiché una discrepanza può dipendere anche dalla loro inadeguatezza.''',formula=r'p=P_{H_0}\{S(T)\ge S(T_{\rm obs})\}',tikz=d('D03',rect(.5,.6,6.9,2)+n(3.7,1.3,'Modello nullo e regola di estremità',w=6.1,size=11)+a(3.7,2.2,3.7,2.9)+rect(.5,3.1,6.9,4.5,'Quantum')+n(3.7,3.8,'Distribuzione della statistica',w=6.1,size=11)+n(3.7,5.6,r'$P_{H_0}\{S(T)\ge S(T_{\rm obs})\}$')),richiamo='La probabilità del p-value riguarda la statistica nel modello di riferimento.',origine='M06:26–28,34–35')
p('Ampiezza dell’effetto e precisione',
'''Una differenza molto piccola può produrre un p-value ridotto quando viene stimata con elevata precisione, mentre una differenza rilevante può rimanere incerta in un campione poco informativo. La figura mantiene un effetto fissato e mostra come la potenza cambi con la numerosità nel modello assunto. La comunicazione deve pertanto riportare la stima nelle unità scientifiche, il suo intervallo e il contesto di campionamento, così che rilevabilità statistica e rilevanza geologica possano essere valutate separatamente.''',figura='M06/F03',didascalia='Potenza teorica approssimata del test t bilaterale a due campioni, effetto 0,3 e deviazione standard 1; numerosità per gruppo.',richiamo='Stima, precisione e rilevanza scientifica contribuiscono a interpretazioni complementari.',origine='M06:29,32–33,39,53')
p('Una soglia non esaurisce la conclusione',
'''P-value pari a 0,049 e 0,051 descrivono livelli di compatibilità molto vicini, sebbene ricadano su lati diversi di una soglia convenzionale. Quando un test non rifiuta il riferimento, la conclusione deve considerare quali effetti rimangano compatibili con l’intervallo stimato. Per sostenere un’equivalenza pratica occorrono margini scientificamente motivati e una procedura dedicata; l’assenza di rifiuto dell’uguaglianza lascia invece aperta la possibilità di informazione insufficiente.''',destra='Una relazione può indicare: differenza stimata, intervallo al livello dichiarato, metodo, numerosità e limiti del disegno. L’eventuale decisione rispetto ad α viene presentata come un passaggio della procedura, conservando il valore numerico e l’incertezza dell’effetto.',richiamo='La conclusione deve essere proporzionata all’intervallo degli effetti ancora compatibili con i dati.',origine='M06:30–35,100–101')

m.sezione_nuova('Errori, potenza e pianificazione')
p('Errori nelle ripetizioni della procedura',
'''L’errore di primo tipo consiste nel rifiutare una specificazione nulla vera, mentre l’errore di secondo tipo riguarda il mancato rifiuto sotto una particolare alternativa. Il livello α controlla il primo rischio entro le condizioni della procedura; la potenza dipende invece dall’effetto alternativo, dalla dispersione e dal disegno. La matrice distingue lo stato del modello dalla decisione ottenuta, evitando di interpretare il livello prefissato come probabilità che una conclusione specifica sia errata.''',formula=r'P_{H_0}(\text{rifiuto})\le\alpha,\qquad\pi(\Delta)=1-\beta(\Delta)',tikz=d('D04',n(4.6,.3,'Stato del riferimento')+n(3,1.2,'Vero')+n(5.8,1.2,'Falso')+n(.8,2.7,'Rifiuto',w=1.4,size=11)+n(.8,4.5,'Mancato rifiuto',w=1.6,size=10.6)+rect(1.8,1.9,4.3,3.6)+rect(4.4,1.9,7,3.6,'Quantum')+rect(1.8,3.7,4.3,5.4,'Quantum')+rect(4.4,3.7,7,5.4)+n(3,2.75,r'$\alpha$')+n(5.7,2.75,r'$1-\beta$')+n(3,4.55,r'$1-\alpha$')+n(5.7,4.55,r'$\beta$')),didascalia='Schema per un riferimento semplice con livello effettivo α e una specifica alternativa.',richiamo='La potenza va riferita a un effetto alternativo definito, con unità e condizioni del modello.',origine='M06:36–41,44–45')
p('La validità vincola i p-value sotto H0',
'''Per un test continuo esatto, il p-value è uniforme sotto l’ipotesi nulla. Più in generale, una procedura valida produce probabilità di p-value inferiori alla soglia non maggiori della soglia stessa; la discrezione può rendere il test conservativo. Simulando molte esecuzioni sotto un riferimento noto, si può quindi controllare la frequenza dei rifiuti e confrontarla con il livello nominale, tenendo conto della variabilità Monte Carlo del controllo.''',formula=r'P_{H_0}(p\le u)\le u,\quad 0\le u\le1',figura='M06/F04',didascalia='P-value di 5.000 test z bilaterali simulati sotto una normale standard. La linea indica la densità uniforme.',richiamo='La frequenza dei rifiuti sotto un modello noto verifica un aspetto operativo della procedura.',origine='M06:37,40,44–45')
p('La pianificazione collega effetto e numerosità',
'''Per due gruppi normali indipendenti con varianza comune nota, una formula approssimata associa la numerosità per gruppo a effetto minimo, livello e potenza desiderata. L’effetto viene espresso nelle unità della risposta e la dispersione deve provenire da informazioni pertinenti al disegno previsto. La formula costituisce un riferimento iniziale: raggruppamenti, perdite e varianze differenti richiedono una pianificazione coerente con tali strutture, eventualmente mediante simulazione.''',formula=r'n\simeq\frac{2\sigma^2(z_{1-\alpha/2}+z_{1-\beta})^2}{\Delta^2}',destra='La pianificazione può partire anche dalla larghezza desiderata dell’intervallo, quando l’obiettivo principale riguarda la precisione della stima. In entrambi i casi, aumentare n riduce una componente di incertezza campionaria, lasciando aperta la valutazione delle distorsioni del disegno.',richiamo='Effetto minimo e precisione desiderata devono derivare dalla domanda scientifica.',origine='M06:39,41–42')
p('La regola di arresto appartiene al disegno',
'''Ripetere il test dopo ogni nuova osservazione e arrestarsi quando il p-value scende sotto la soglia modifica la probabilità complessiva di rifiuto. Una procedura calibrata per una numerosità fissata perde quindi il proprio riferimento se viene utilizzata con una regola sequenziale diversa. Il diagramma mostra la selezione introdotta dall’arresto; un’analisi sequenziale valida richiede invece una regola progettata e calibrata per le occasioni di esame previste.''',tikz=d('D05',rect(.4,.6,3.1,2)+n(1.75,1.3,'Nuovi dati',w=2.4)+a(3.3,1.3,4,1.3)+rect(4.2,.6,7,2,'Quantum')+n(5.6,1.3,'Ricalcolo di p',w=2.5,size=11)+a(5.6,2.2,5.6,3.2)+n(5.6,3.9,'Arresto se p < α',w=2.8,size=11)+r'\draw[arr] (4.1,3.9)--(1.75,3.9)--(1.75,2.2);'+n(1.75,5,'Altrimenti continua',w=2.8,size=11)+n(3.7,6,'La regola seleziona il momento della conclusione.',w=6.8,size=10.6)),richiamo='Numero delle analisi intermedie e regola di arresto devono essere inclusi nella procedura.',origine='M06:43')

m.sezione_nuova('Due medie indipendenti: Welch')
p('La varianza del contrasto combina due contributi',
'''La varianza della differenza fra due medie indipendenti somma i contributi dei gruppi. Le varianze campionarie stimano quindi l’errore standard usato da Welch, che ammette dispersioni differenti. La statistica rapporta lo scostamento dal valore nullo alla sua incertezza. Sotto normalità, la distribuzione t con gradi di libertà di Welch–Satterthwaite fornisce un riferimento approssimato.''',formula=r'\widehat\Delta=\bar x_1-\bar x_2,\quad SE=\sqrt{\frac{s_1^2}{n_1}+\frac{s_2^2}{n_2}}\\ t_W=\frac{\widehat\Delta-\Delta_0}{SE}',destra='La formula richiede indipendenza fra gruppi e fra unità entro ciascun gruppo. Provini dello stesso sito possono condividere componenti di variabilità, per cui la numerosità effettiva richiede un modello del raggruppamento.',richiamo='Welch ammette varianze differenti, mantenendo necessarie le ipotesi sulla dipendenza.',origine='M06:46–49,52')
p('I gradi di libertà riflettono la stima della variabilità',
'''La correzione di Welch–Satterthwaite combina i contributi delle varianze campionarie, attribuendo maggiore influenza ai termini che dominano l’errore standard. I gradi di libertà possono essere non interi, poiché derivano da un’approssimazione della distribuzione del denominatore. L’intervallo bilaterale viene costruito aggiungendo e sottraendo alla differenza il quantile t moltiplicato per l’errore standard. Test e intervallo risultano coerenti quando utilizzano lo stesso contrasto, livello e modello.''',formula=r'\nu=\frac{(s_1^2/n_1+s_2^2/n_2)^2}{\frac{(s_1^2/n_1)^2}{n_1-1}+\frac{(s_2^2/n_2)^2}{n_2-1}}\\ IC_{1-\alpha}:\ \widehat\Delta\pm t_{\nu,1-\alpha/2}SE',tikz=d('D06',n(3.7,.5,'Intervallo del contrasto')+linea(.6,3,7,3)+linea(1,2.7,1,3.3)+n(1,3.9,'0')+r'\draw[Classical,line width=2pt] (2.692,3)--(6.292,3);'+n(4.492,3,r'$\bullet$')+n(2.692,4.1,'0,282')+n(6.292,4.1,'0,882')+n(4.492,1.8,'0,582 µm')+n(3.7,5.6,'Stima e intervallo su una scala lineare.',w=6.8,size=11)),richiamo='L’intervallo esprime l’incertezza della differenza nelle unità della risposta.',origine='M06:49–51')
c=estratto('M06','welch',"d <- read.csv('dati/fossili_simulati.csv')\nx <- d$diametro_tot_um[d$morfotipo=='Spiky']\ny <- d$diametro_tot_um[d$morfotipo=='Rounded']\nw <- t.test(x,y,var.equal=FALSE)\nc(differenza=mean(x)-mean(y),\n  t=unname(w$statistic),df=unname(w$parameter),\n  p=w$p.value)\nw$conf.int")
p('Il risultato viene letto nel verso dichiarato',
'''Nel dataset sintetico, il diametro medio degli Spiky supera quello dei Rounded di circa 0,582 µm; l’intervallo di Welch al 95% va da 0,282 a 0,882 µm. Il test restituisce t circa 3,831, con 156,89 gradi di libertà e p circa 0,000184. Questi numeri descrivono il confronto entro il modello di osservazioni indipendenti. La rilevanza della differenza e la sua trasferibilità a un contesto geologico richiederebbero informazioni ulteriori sul processo di raccolta e sulle popolazioni rappresentate.''',codice=c,richiamo='L’ordine degli argomenti della funzione determina il segno della differenza riportata.',origine='M06:48–55')

m.sezione_nuova('Confronti appaiati')
p('La differenza entro coppia diventa la risposta',
'''Per ciascun provino misurato prima e dopo, il cambiamento viene definito sottraendo la prima misura dalla seconda. L’analisi riguarda quindi una variabile per coppia, la cui distribuzione dipende dalla covarianza fra le due misure. Una correlazione positiva può ridurre la variabilità delle differenze rispetto a quella che si otterrebbe ignorando l’abbinamento. La validità del confronto richiede tuttavia che le coppie siano indipendenti secondo il disegno considerato.''',formula=r'D_i=Y_{i,\mathrm{dopo}}-Y_{i,\mathrm{prima}}\\ \operatorname{Var}(D)=\operatorname{Var}(Y_d)+\operatorname{Var}(Y_p)-2\operatorname{Cov}(Y_d,Y_p)',figura='M06/F05',didascalia='Ventiquattro provini sintetici; ogni segmento collega le due misure dello stesso identificativo.',richiamo='La chiave della coppia deve essere conservata durante importazione, filtri e ordinamenti.',origine='M06:56–59,62')
p('Il test appaiato è un test sulla media delle differenze',
'''Quando le differenze sono indipendenti e normalmente distribuite, la media standardizzata segue esattamente una t con n−1 gradi di libertà sotto il valore nullo. L’esame delle condizioni riguarda quindi le differenze, mentre le distribuzioni marginali di prima e dopo possono avere caratteristiche diverse. In assenza di normalità, l’approssimazione richiede una valutazione della numerosità e della forma, soprattutto se pochi cambiamenti estremi dominano la stima.''',formula=r't=\frac{\bar D-\Delta_0}{s_D/\sqrt n}\sim t_{n-1}\ \text{sotto }H_0\\ IC:\ \bar D\pm t_{n-1,1-\alpha/2}\frac{s_D}{\sqrt n}',tikz=d('D07',n(1.5,.5,'Prima')+n(5.8,.5,'Dopo')+''.join(n(1.5,1.5+j*1.2,f'P{j+1}')+n(5.8,1.5+j*1.2,f'P{j+1}')+a(2.2,1.5+j*1.2,4.9,1.5+j*1.2)+n(3.55,1.05+j*1.2,r'$D_{%d}$'%(j+1),size=11) for j in range(3))+n(3.7,5.6,r'$\bar D,\quad s_D,\quad n_{\rm coppie}$')),richiamo='Le condizioni del test appaiato riguardano il vettore delle differenze entro coppia.',origine='M06:58–61')
c=estratto('M06','appaiato',"d <- read.csv('dati/misure_appaiate_simulate.csv')\nstopifnot(!anyDuplicated(d$id))\nD <- d$dopo-d$prima\na <- t.test(D)\nb <- t.test(d$dopo,d$prima,paired=TRUE)\nstopifnot(isTRUE(all.equal(a$p.value,b$p.value)))\nc(media=mean(D),a$conf.int)")
p('L’identità fra due chiamate verifica il calcolo',
'''L’analisi diretta delle differenze e la chiamata con paired=TRUE devono produrre lo stesso confronto, purché gli argomenti mantengano ordine e corrispondenza. Nei ventiquattro provini, il cambiamento medio è circa 0,03573 nelle unità delle misure, con intervallo al 95% da 0,02278 a 0,04868. Il codice controlla l’unicità degli identificativi e l’accordo fra le due implementazioni, collegando la definizione matematica al comportamento della funzione.''',codice=c,richiamo='Un controllo equivalente permette di verificare abbinamento, segno e specificazione della procedura.',origine='M06:60,63–65')

m.sezione_nuova('Ranghi e ipotesi sulla distribuzione')
p('Il confronto dei ranghi usa l’ordinamento congiunto',
'''Il test rank-sum confronta la posizione dei valori di un gruppo nell’ordinamento dell’insieme. Sotto il riferimento di distribuzioni identiche e osservazioni indipendenti, le etichette sono scambiabili rispetto ai ranghi. La statistica può essere espressa attraverso il numero di confronti a coppie nei quali un valore del primo gruppo supera uno del secondo, attribuendo metà contributo ai pareggi. L’interpretazione di posizione richiede forme coerenti fra gruppi.''',formula=r'U=\sum_{i=1}^{n_1}\sum_{j=1}^{n_2}\left[\mathbf1(x_i>y_j)+\tfrac12\mathbf1(x_i=y_j)\right]\\ \widehat\theta=\frac{U}{n_1n_2}',destra='La quantità θ stima P(X>Y)+½P(X=Y). Il test usuale è calibrato sul riferimento di uguale distribuzione; la sola condizione θ=½, con forme differenti, richiede ulteriori considerazioni sulla calibrazione.',richiamo='La misura basata sui ranghi deve essere associata all’ipotesi per cui il test è calibrato.',origine='M06:66–70,73–75')
p('La mediana comune lascia indeterminata la forma',
'''Due distribuzioni possono condividere la mediana e differire per dispersione o asimmetria. La figura mostra un esempio simmetrico con la stessa posizione centrale e scale differenti, nel quale l’ordinamento complessivo contiene informazioni ulteriori rispetto alle mediane. Il rank-sum non costituisce un test universale capace di rilevare ogni differenza di forma; in particolare, differenze di scala simmetriche possono lasciare invariata la probabilità di superiorità. La scelta del confronto deve quindi partire dalla caratteristica scientifica da esaminare.''',figura='M06/F06',didascalia='Due densità normali teoriche con mediana zero e deviazioni standard 1 e 2. Per simmetria, P(X>Y)=1/2.',richiamo='L’uguaglianza delle mediane e l’uguaglianza delle distribuzioni sono ipotesi distinte.',origine='M06:68–69,74–75')
p('Il signed-rank richiede simmetria delle differenze',
'''Nel confronto appaiato basato sui ranghi, si ordinano i valori assoluti delle differenze e si sommano i ranghi associati a un segno. Il riferimento usuale richiede differenze indipendenti e simmetriche rispetto al centro nullo. La gestione di zeri e pareggi modifica il calcolo della distribuzione e delle approssimazioni; versione del software e opzioni devono quindi accompagnare il risultato. Quando interessa soltanto la probabilità di un cambiamento positivo, un test sui segni risponde a una domanda più specifica, utilizzando meno informazione sulle ampiezze.''',formula=r'W^+=\sum_{i:D_i>0}\operatorname{rank}(|D_i|)',tikz=d('D08',n(1.1,.5,'D')+n(3.6,.5,'|D|')+n(6.1,.5,'Rango')+''.join(n(1.1,1.6+j,str(v))+n(3.6,1.6+j,str(abs(v)))+n(6.1,1.6+j,str(k),color='Classical' if v>0 else 'Quantum') for j,(v,k) in enumerate([(-2,2),(1,1),(4,3)]))+n(3.7,5.3,r'$W^+=1+3=4$')),richiamo='Il riferimento del signed-rank riguarda la simmetria delle differenze attorno al centro nullo.',origine='M06:70–73')
c=estratto('M06','ranghi',"d <- read.csv('dati/fossili_simulati.csv')\nx <- d$diametro_tot_um[d$morfotipo=='Spiky']\ny <- d$diametro_tot_um[d$morfotipo=='Rounded']\nwilcox.test(x,y,exact=FALSE,correct=TRUE)\nU <- sum(outer(x,y,'>'))+\n .5*sum(outer(x,y,'=='))\nU/(length(x)*length(y))")
p('La procedura viene scelta prima del risultato',
'''Provare più test e selezionare quello con il p-value più piccolo introduce una selezione che il singolo p-value riportato non rappresenta. Un’analisi di sensibilità può invece confrontare procedure motivate, dichiarando la differenza fra le quantità e le ipotesi esaminate. Il codice specifica l’approssimazione normale e la correzione di continuità del rank-sum, affiancando una misura di superiorità probabilistica che rende leggibile il contenuto dell’ordinamento.''',codice=c,richiamo='Le analisi alternative devono essere motivate e riportate insieme alle rispettive ipotesi.',origine='M06:70,72–73,99')

m.sezione_nuova('Conteggi e associazione fra categorie')
p('I conteggi attesi derivano dall’indipendenza',
'''Una tabella di contingenza conserva i conteggi congiunti e i totali marginali. Sotto indipendenza fra categorie, la quota attesa in una cella è il prodotto delle quote marginali, dal quale si ricava il conteggio atteso. La statistica di Pearson somma gli scarti quadratici fra osservati e attesi, standardizzati per il valore atteso. L’approssimazione chi-quadrato richiede condizioni sulle frequenze e sul disegno di campionamento, oltre all’indipendenza delle unità osservate.''',formula=r'E_{ij}=\frac{n_{i+}n_{+j}}n,\qquad X^2=\sum_{i,j}\frac{(O_{ij}-E_{ij})^2}{E_{ij}}\\ df=(r-1)(c-1)',destra='Nel caso 2×2, le opzioni di correzione di continuità cambiano il valore della statistica. Per conteggi piccoli si può ricorrere a procedure esatte o a una calibrazione Monte Carlo appropriata al riferimento.',richiamo='Il test usa conteggi e struttura della tabella, mentre le percentuali ne facilitano l’interpretazione.',origine='M06:76–81')
p('Le percentuali si accompagnano ai conteggi',
'''Nel sito A si osservano diciotto presenze su trenta unità e nel sito B nove su trenta, corrispondenti al 60% e al 30%. Il totale delle presenze è ventisette e, sotto indipendenza con uguali numerosità di sito, il conteggio atteso delle presenze è 13,5 in ciascun sito. La figura mostra le quote conservando i denominatori, mentre il confronto statistico viene eseguito sulla tabella dei conteggi. Un’associazione osservata richiede ancora una valutazione delle condizioni ambientali e della selezione dei siti.''',figura='M06/F07',didascalia='Esempio costruito: trenta unità per sito. I segmenti rappresentano le proporzioni di presenza e assenza.',richiamo='La differenza nelle frequenze deve essere interpretata rispetto al disegno e alle possibili variabili condivise.',origine='M06:78–85')
c=estratto('M06','contingenza',"tab <- matrix(c(18,12,9,21),nrow=2,byrow=TRUE,\n dimnames=list(sito=c('A','B'),\n esito=c('Presenza','Assenza')))\nprop.table(tab,1)\nq <- chisq.test(tab,correct=FALSE)\nq$expected\nq\nfisher.test(tab)")
p('Il riferimento esatto condiziona sui margini',
'''Nel test esatto di Fisher per una tabella 2×2, il riferimento usuale considera le tabelle compatibili con i margini osservati sotto l’ipotesi nulla di odds ratio unitario. Questa costruzione differisce dall’approssimazione chi-quadrato, per cui risultati numerici diversi possono derivare da riferimenti e convenzioni differenti. Il codice rende visibile la tabella attesa e specifica l’assenza della correzione di continuità nel confronto di Pearson, consentendo di ricostruire ciascun calcolo.''',codice=c,formula=r'P(A=a\mid\text{margini})=\frac{\binom{n_{+1}}a\binom{n_{+2}}{n_{1+}-a}}{\binom n{n_{1+}}}',richiamo='Il metodo esatto deve essere descritto attraverso il suo riferimento e le quantità su cui condiziona.',origine='M06:80–85')

m.sezione_nuova('Più gruppi e confronti multipli')
p('L’ANOVA scompone la variabilità totale',
'''Con errori indipendenti, normali e omoscedastici, l’ANOVA confronta la variabilità delle medie con la dispersione interna. La somma quadratica totale si scompone nei contributi fra ed entro gruppi. Sotto l’uguaglianza delle medie, il rapporto fra quadrati medi segue una distribuzione F. Un rifiuto globale segnala che almeno una media differisce; i contrasti successivi richiedono controllo della molteplicità.''',formula=r'SS_T=SS_B+SS_W\\ SS_B=\sum_g n_g(\bar x_g-\bar x)^2\\ F=\frac{SS_B/(G-1)}{SS_W/(N-G)}',tikz=d('D09',rect(.5,1.2,6.9,2.7)+n(3.7,1.95,r'$SS_T$')+a(2.2,3,1.9,4)+a(5.2,3,5.5,4,'Quantum')+rect(.5,4.2,3.3,5.6)+n(1.9,4.9,r'$SS_B$')+rect(4.1,4.2,6.9,5.6,'Quantum')+n(5.5,4.9,r'$SS_W$')+n(3.7,.4,'Variabilità totale')),richiamo='Il confronto globale riguarda l’uguaglianza delle medie sotto le condizioni del modello.',origine='M06:86–88')
p('Il confronto globale può ammettere varianze diverse',
'''L’estensione di Welch a più gruppi utilizza pesi inversamente proporzionali alla varianza stimata delle medie. La media di riferimento attribuisce quindi peso maggiore ai gruppi con stime più precise, mentre una correzione della statistica e dei gradi di libertà tiene conto della stima delle varianze. In R, oneway.test con var.equal=FALSE implementa questa procedura. L’interpretazione continua a riguardare le medie e richiede una struttura di indipendenza coerente con i dati.''',formula=r'w_g=\frac{n_g}{s_g^2},\qquad \bar x_w=\frac{\sum_g w_g\bar x_g}{\sum_gw_g}',destra='Nel laboratorio sulle rocce sintetiche, il confronto della densità per litologia può essere eseguito con oneway.test(densita ~ litologia_generatrice, data=d, var.equal=FALSE). La scelta dei contrasti successivi deve derivare dalla domanda e dalla famiglia di confronti dichiarata.',richiamo='La scelta fra ANOVA omoscedastica e Welch richiede una valutazione del modello della variabilità.',origine='M06:89')
p('La famiglia dei test determina il rischio complessivo',
'''Con m test indipendenti, tutti sotto ipotesi nulle vere e ciascuno di livello α, la probabilità di almeno un rifiuto è uno meno la probabilità che nessun test rifiuti. Per dieci confronti al 5%, il rischio ideale è circa 40,1%. La formula richiede indipendenza e livelli effettivi esatti; in altri casi la dipendenza modifica il calcolo. Definire la famiglia dei test permette di stabilire quale rischio complessivo debba essere controllato.''',formula=r'FWER=1-(1-\alpha)^m\\ 1-0,95^{10}\simeq0,4013',figura='M06/F08',didascalia='Rischio teorico di almeno un falso rifiuto per test indipendenti al livello 0,05 sotto tutte le ipotesi nulle vere.',richiamo='Il numero delle domande esaminate appartiene alla descrizione dell’evidenza.',origine='M06:90,92–95')
p('Holm confronta p-value ordinati con soglie crescenti',
'''La procedura di Holm ordina i p-value dal più piccolo al più grande e li confronta con soglie α diviso il numero delle ipotesi ancora considerate. Si procede finché un confronto non soddisfa la soglia, arrestando i rifiuti successivi. Il metodo controlla fortemente la probabilità di almeno un falso rifiuto quando i p-value marginali sono validi, anche con dipendenza fra i test. Il diagramma mostra la sequenza delle soglie per una famiglia di quattro ipotesi.''',formula=r'p_{(j)}\le\frac\alpha{m-j+1},\quad j=1,\ldots,m',tikz=d('D10',n(1.4,.5,'Ordine')+n(5,.5,'Soglia')+''.join(rect(.5,1+j*1.1,6.9,1.9+j*1.1,'Classical' if j%2==0 else 'Quantum')+n(1.5,1.45+j*1.1,r'$p_{(%d)}$'%(j+1))+n(5.1,1.45+j*1.1,t) for j,t in enumerate([r'$\alpha/4$',r'$\alpha/3$',r'$\alpha/2$',r'$\alpha$']))+n(3.7,5.9,'Arresto al primo confronto non soddisfatto.',w=6.8,size=10.6)),richiamo='La famiglia deve includere le domande rispetto alle quali si intende controllare l’errore complessivo.',origine='M06:91–95')
c=estratto('M06','holm',"p <- c(.003,.018,.041,.2)\np_adj <- p.adjust(p,method='holm')\ndata.frame(p,p_adj,rifiuto=p_adj<=.05)\nstopifnot(isTRUE(all.equal(\n unname(p_adj),c(.012,.054,.082,.2))))")
p('Il risultato corretto conserva la famiglia originaria',
'''Per i quattro p-value dell’esempio, Holm restituisce valori corretti 0,012, 0,054, 0,082 e 0,2. Al livello familiare del 5% viene quindi rifiutata soltanto la prima ipotesi. La correzione deve essere applicata alla famiglia definita, includendo anche risultati poco favorevoli alla conclusione attesa. Un’analisi esplorativa può esaminare molte variabili, purché il percorso venga documentato e le verifiche successive siano progettate tenendo conto della selezione delle ipotesi.''',codice=c,richiamo='La selezione dei soli risultati favorevoli altera il significato della correzione per molteplicità.',origine='M06:91–95')

m.sezione_nuova('Relazione e verifica del confronto')
p('La relazione ricostruisce una catena di argomenti',
'''La consegna presenta una domanda, il contrasto con verso e unità, la struttura del campione e la rappresentazione dei dati. Il metodo viene motivato attraverso le ipotesi che ne sostengono la calibrazione, mentre il risultato combina stima, intervallo e p-value con una discussione della rilevanza. Le analisi di sensibilità devono dichiarare quali scelte cambino e quali quantità restino confrontabili. La lettura critica verifica infine se la conclusione rispetti il disegno e l’informazione effettivamente disponibile.''',destra='Scegliere un confronto indipendente, appaiato o categoriale. Consegnare script, tabella dei risultati e figura; indicare eventuale famiglia di test e correzione. La verifica deve riprodurre almeno un risultato mediante un calcolo equivalente e distinguere osservazioni campionarie, ipotesi del modello e conclusioni.',richiamo='La qualità del confronto dipende dalla coerenza fra disegno, quantità stimata e conclusione.',origine='M06:96–107,110')
p('Riferimenti per test e interpretazione',
'''La documentazione di t.test, wilcox.test, chisq.test, fisher.test, oneway.test e p.adjust precisa ipotesi, opzioni e convenzioni delle procedure utilizzate. La dichiarazione dell’American Statistical Association sui p-value sviluppa i limiti delle interpretazioni fondate esclusivamente su una soglia. Nel progetto, gli script associano i confronti ai dati distribuiti e verificano formule mediante risultati delle funzioni, conservando versione dell’ambiente e specifiche dei calcoli.''',destra='R Core Team: documentazione delle funzioni stats richiamate nel modulo.\n\nWasserstein e Lazar, 2016: The ASA Statement on p-Values: Context, Process, and Purpose.\n\nURL e registro delle verifiche sono inclusi nei materiali del corso.',richiamo='Ipotesi e opzioni del metodo devono restare accessibili insieme al risultato numerico.',origine='M06:108–109',fonti='R Core Team · ASA')
m.salva()
